package dustin.cex.domains.kyc;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import dustin.cex.domains.auth.model.entity.*;
import dustin.cex.domains.cdd.CustomerDeclaration;
import dustin.cex.domains.edd.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.web.server.ResponseStatusException;

/** 두 현재 담당자 부재의 발견·독립 복구와 계정 복구/재상실 뒤 옛 서명 무효화를 검증한다. */
class CustomerWorkRecoveryIntegrationTest extends CustomerWorkTestSupport {
    Account requester;CustomerWorkCustodyService.Cursor beginning;
    @BeforeEach void recoverySetup() throws Exception {
        requester=account(UserRole.OPERATOR);var rows=jdbc.queryForList("SELECT id,created_at FROM customer_exit_review_requests WHERE id<>? ORDER BY created_at DESC,id DESC LIMIT 1",receipt.id());beginning=rows.isEmpty()?null:new CustomerWorkCustodyService.Cursor(((Timestamp)rows.getFirst().get("created_at")).toInstant(),(UUID)rows.getFirst().get("id"));
    }
    void orphan(){disable(maker);disable(checker);}
    CustomerWorkCustodyService.Orphans orphans(){return handoffs.orphans(requester.user().getId(),requester.sid(),beginning);}
    @Test void outsideRequesterSeesOnlyOrphanMetadataBeforeIndependentApproval() throws Exception {orphan();var item=orphans().items().getFirst();assertEquals(receipt.id(),item.reviewId());assertTrue(item.orphaned());String raw=json.writeValueAsString(orphans());for(String w:List.of("고객 사유","비공개 처리 기록","reasonMac","payloadHash"))assertFalse(raw.contains(w));assertThrows(ResponseStatusException.class,()->requests.inspect(requester.user().getId(),requester.sid(),receipt.id()));var r=proposal(requester,UUID.randomUUID());assertEquals(CustomerWorkCustodyService.Mode.RECOVERY,r.payload().mode());decideHandoff(independent,r,true,handoffProof(independent,r,true));assertNotNull(requests.inspect(nextPrimary.user().getId(),nextPrimary.sid(),receipt.id()));assertThrows(ResponseStatusException.class,()->requests.inspect(requester.user().getId(),requester.sid(),receipt.id()));assertEquals(1,active());blocked();}
    @Test void oneAvailablePersonPreventsOutsideRecovery() throws Exception {disable(maker);assertTrue(orphans().items().isEmpty());assertThrows(ResponseStatusException.class,()->context(requester));assertThrows(ResponseStatusException.class,()->handoffs.propose(requester.user().getId(),requester.sid(),receipt.id(),"0".repeat(64),nextPrimary.user().getId(),nextChecker.user().getId(),UUID.randomUUID(),"외부 복구 시도"));}
    @ParameterizedTest @ValueSource(strings={"disabled","expired","recovery","role","identity"})
    void eachActualLossOfBothCurrentPeopleAllowsRecovery(String how) throws Exception {for(var a:List.of(maker,checker)){var u=users.findById(a.user().getId()).orElseThrow();switch(how){case "disabled"->u.setEnabled(false);case "expired"->u.setOperatorAccessExpiresAt(Instant.now().minusSeconds(1));case "recovery"->u.setOperatorRecoveryRequestId(UUID.randomUUID());case "role"->u.setRole(UserRole.AUDITOR);case "identity"->u.setOperatorPersonId(UUID.randomUUID());default->throw new AssertionError();}users.saveAndFlush(u);}assertEquals(receipt.id(),orphans().items().getFirst().reviewId());var r=proposal(requester,UUID.randomUUID());decideHandoff(independent,r,true,handoffProof(independent,r,true));assertEquals(1,context(nextPrimary).generation());}
    @Test void staleMfaOfCurrentPeopleDoesNotMeanTheirAuthorityIsGone() throws Exception {for(var a:List.of(maker,checker)){var t=tokens.findBySessionId(a.sid()).orElseThrow();t.setMfaVerifiedAt(LocalDateTime.now().minusMinutes(6));tokens.saveAndFlush(t);}assertTrue(orphans().items().isEmpty());assertThrows(ResponseStatusException.class,()->context(requester));}
    @Test void reactivatedMemberPreventsRecoveryAndSecondLossDoesNotReviveOldProof() throws Exception {orphan();var r=proposal(requester,UUID.randomUUID());var proof=handoffProof(independent,r,true);var u=users.findById(maker.user().getId()).orElseThrow();u.setEnabled(true);users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->decideHandoff(independent,r,true,proof));disable(maker);assertThrows(ResponseStatusException.class,()->decideHandoff(independent,r,true,proof));assertEquals(0,context(requester).generation());}
    @Test void oldMemberVersionChangeAlsoInvalidatesPendingNormalTransfer() throws Exception {var r=proposal(maker,UUID.randomUUID());var proof=handoffProof(independent,r,true);var u=users.findById(checker.user().getId()).orElseThrow();u.setUsername("기존 담당자 변경");users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->decideHandoff(independent,r,true,proof));assertEquals(0,context(maker).generation());}
    @Test void rejectionPreservesOrphanAndAllowsNewRequest() throws Exception {orphan();var r=proposal(requester,UUID.randomUUID());decideHandoff(independent,r,false,handoffProof(independent,r,false));assertEquals(1,orphans().items().size());assertNotNull(proposal(requester,UUID.randomUUID()));}
    @Test void successfulRecoveryLeavesOrphanListWithoutHidingHistory() throws Exception {orphan();var r=proposal(requester,UUID.randomUUID());decideHandoff(independent,r,true,handoffProof(independent,r,true));assertTrue(orphans().items().isEmpty());assertEquals(note,notes.list(nextPrimary.user().getId(),nextPrimary.sid(),receipt.id(),0).getFirst());assertEquals(List.of(reply),replies.own(customer.getId(),sid,receipt.id(),0));assertEquals("APPROVED",handoffs.status(requester.user().getId(),requester.sid(),r.payload().id()).status());}
    @Test void recoveryCannotGrantOriginalFinancialAuthority() throws Exception {orphan();var r=proposal(requester,UUID.randomUUID());decideHandoff(independent,r,true,handoffProof(independent,r,true));assertThrows(ResponseStatusException.class,()->reporting.inspect(nextPrimary.user().getId(),nextPrimary.sid(),original.payload().id(),0));assertThrows(ResponseStatusException.class,()->rescissions.propose(nextPrimary.user().getId(),nextPrimary.sid(),original.payload().id(),independent.user().getId(),UUID.randomUUID(),withdrawalFacts()));}
    @Test void lostRequesterAuthorityPreventsUsingItsPendingRecovery() throws Exception {orphan();var r=proposal(requester,UUID.randomUUID());disable(requester);assertThrows(ResponseStatusException.class,()->handoffs.inspect(independent.user().getId(),independent.sid(),r.payload().id()));}
    @Test void orphanDiscoveryAuditFailureReturnsNoMetadata() throws Exception {orphan();doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_WORK_ORPHANS_READ"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,this::orphans);reset(audit);assertEquals(1,orphans().items().size());}
    @Test void malformedCursorAndForeignSessionAreRejected() throws Exception {assertThrows(ResponseStatusException.class,()->handoffs.orphans(requester.user().getId(),maker.sid(),beginning));for(var c:List.of(new CustomerWorkCustodyService.Cursor(null,UUID.randomUUID()),new CustomerWorkCustodyService.Cursor(Instant.now(),null),new CustomerWorkCustodyService.Cursor(Instant.now().plusSeconds(60),UUID.randomUUID()),new CustomerWorkCustodyService.Cursor(Instant.EPOCH.minusSeconds(1),UUID.randomUUID())))assertThrows(ResponseStatusException.class,()->handoffs.orphans(requester.user().getId(),requester.sid(),c));}
    @Test void httpRecoveryDiscoveryRequiresCurrentOperatorAndNoStore() throws Exception {orphan();String path="/api/admin/compliance/customer-review-orphans";var q=get(path).header("Authorization","Bearer "+requester.access());if(beginning!=null)q.param("afterReceived",beginning.receivedAt().toString()).param("afterRequest",beginning.requestId().toString());String raw=mvc.perform(q).andExpect(status().isOk()).andExpect(header().string("Cache-Control",org.hamcrest.Matchers.containsString("no-store"))).andReturn().getResponse().getContentAsString();assertTrue(raw.contains(receipt.id().toString()));mvc.perform(get(path).header("Authorization","Bearer "+customerAccess)).andExpect(status().isForbidden());mvc.perform(get(path).header("Authorization","Bearer "+account(UserRole.AUDITOR).access())).andExpect(status().isForbidden());mvc.perform(get(path)).andExpect(status().isUnauthorized());}
}
